const $=s=>document.querySelector(s);const state={topics:new Set(Object.keys(TOPICS)),query:'',view:'map',zoom:1,route:false};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const route=['sketchpad','simula','smalltalk'];
const matches=e=>state.topics.has(e.topic)&&(!state.route||route.includes(e.id))&&[e.title,e.text,...e.people,...e.orgs].join(' ').toLocaleLowerCase('ru').includes(state.query);
function openDialog(html){$('#detail-content').innerHTML=html;if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0;}
function sourceHTML(key){const [title,url]=SOURCES[key];return `<a class="source" href="${url}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;}
function openEvent(id){const e=EVENTS.find(e=>e.id===id);if(!e)return;const links=LINKS.filter(l=>l.from===id||l.to===id);openDialog(`<div class="eyebrow">${e.year} / ${TOPICS[e.topic].name}</div><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><h3>КАКУЮ ПРОБЛЕМУ РЕШАЛИ</h3><p>${esc(e.problem)}</p><h3>ЧТО ИЗМЕНИЛОСЬ</h3><p>${esc(e.meaning)}</p><h3>ЛЮДИ И ИНСТИТУТЫ</h3><div class="tags">${e.people.map(p=>`<button data-entity="${esc(p)}" data-kind="people">${esc(p)}</button>`).join('')}${e.orgs.map(p=>`<button data-entity="${esc(p)}" data-kind="orgs">${esc(p)}</button>`).join('')}</div>${e.note?`<p class="note">${esc(e.note)}</p>`:''}<h3>СВЯЗИ · ${links.length}</h3>${links.length?links.map(l=>{const other=EVENTS.find(x=>x.id===(l.from===id?l.to:l.from));return `<button class="related" data-event="${other.id}">${l.from===id?'→':'←'} ${other.year} · ${esc(other.title)}<span>${esc(l.text)}</span></button>${sourceHTML(l.source)}`;}).join(''):'<p>Подтверждённые связи пока не добавлены. Это не означает их отсутствия.</p>'}<h3>ИСТОЧНИКИ</h3>${e.sources.map(sourceHTML).join('')}`);}
function openEntity(name,kind){const ev=EVENTS.filter(e=>e[kind].includes(name)).sort((a,b)=>a.year-b.year);openDialog(`<div class="eyebrow">${kind==='people'?'ЧЕЛОВЕК':'ИНСТИТУТ'}</div><h2>${esc(name)}</h2><p>Участие в событиях начальной выборки. Одинаковое участие не означает прямого знакомства или сотрудничества.</p>${ev.map(e=>`<button class="related" data-event="${e.id}">${e.year} · ${esc(e.title)}<span>${esc(e.orgs.join(' / '))}</span></button>`).join('')}`);}
function render(){const events=EVENTS.filter(matches);$('#result-count').textContent=`${events.length} из ${EVENTS.length} событий · 3 линии истории`;$('#zoom-label').textContent=`${Math.round(state.zoom*100)}%`;$('#minus').disabled=state.zoom<=1;$('#plus').disabled=state.zoom>=1.8;$('#footer-text').textContent=state.route?'Маршрут: два источника идей → Smalltalk':'История не развивается по прямой';$('#map-scroll').hidden=state.view!=='map';$('#directory').hidden=state.view==='map';
if(state.view!=='map'){const map=new Map;events.forEach(e=>e[state.view].forEach(n=>{if(!map.has(n))map.set(n,[]);map.get(n).push(e);}));$('#directory').innerHTML=[...map].sort((a,b)=>a[0].localeCompare(b[0],'ru')).map(([name,ev])=>`<button class="directory-item" data-entity="${esc(name)}" data-kind="${state.view}"><strong>${esc(name)}</strong><small>${ev.length} событий · ${Math.min(...ev.map(e=>e.year))}—${Math.max(...ev.map(e=>e.year))}<br>${esc([...new Set(ev.flatMap(e=>state.view==='people'?e.orgs:e.people))].slice(0,3).join(' / '))}</small></button>`).join('')||'<div class="empty">Ничего не найдено.<br>Попробуйте другое имя или сбросьте фильтры.</div>';return;}
const step=64*state.zoom,width=step*48+210;$('#canvas').style.width=width+'px';$('#axis').innerHTML=Array.from({length:10},(_,i)=>1945+i*5).map(y=>`<span style="left:${(y-1945)*step+30}px">${y}</span>`).join('');const pos={};const occupied={chip:[],oop:[],net:[]};EVENTS.forEach(e=>{let x=(e.year-1945)*step+30;const arr=occupied[e.topic];let row=0;while(arr[row]!==undefined&&x<arr[row]+175)row++;arr[row]=x;const y={chip:60,oop:270,net:480}[e.topic]+row*104;pos[e.id]={x,y};});
$('#nodes').innerHTML=events.map(e=>`<button class="event" data-event="${e.id}" data-topic="${e.topic}" style="left:${pos[e.id].x}px;top:${pos[e.id].y}px"><span class="year">${e.year}<span>↗</span></span><strong>${esc(e.title)}</strong><small>${esc(e.orgs[0])}</small></button>`).join('')||'<div class="empty">Ничего не найдено. Попробуйте другой запрос.</div>';
const ids=new Set(events.map(e=>e.id));$('#edges').innerHTML=LINKS.filter(l=>ids.has(l.from)&&ids.has(l.to)).map(l=>{const a=pos[l.from],b=pos[l.to],color=TOPICS[EVENTS.find(e=>e.id===l.from).topic].color;const ax=a.x+164,ay=a.y+45,bx=b.x,by=b.y+45;return `<path d="M ${ax} ${ay} C ${ax+45} ${ay},${bx-45} ${by},${bx} ${by}" fill="none" stroke="${color}" stroke-opacity=".4" ${l.type==='idea'?'stroke-dasharray="5 5"':''}/><circle cx="${bx}" cy="${by}" r="2.5" fill="${color}"/>`;}).join('');}
$('#topics').innerHTML=Object.entries(TOPICS).map(([key,t])=>`<label style="color:${t.color}"><input type="checkbox" value="${key}" checked>${t.name}<span class="count">${EVENTS.filter(e=>e.topic===key).length}</span></label>`).join('');
$('#topics').addEventListener('change',e=>{if(e.target.checked)state.topics.add(e.target.value);else state.topics.delete(e.target.value);state.route=false;render();});$('#search').addEventListener('input',e=>{state.query=e.target.value.trim().toLocaleLowerCase('ru');render();});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{state.view=b.dataset.view;document.querySelectorAll('[data-view]').forEach(t=>t.classList.toggle('active',t===b));render();});
document.addEventListener('click',e=>{const event=e.target.closest('[data-event]');if(event)openEvent(event.dataset.event);const entity=e.target.closest('[data-entity]');if(entity)openEntity(entity.dataset.entity,entity.dataset.kind);});
$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
$('#plus').onclick=()=>{state.zoom=Math.min(1.8,+(state.zoom+.2).toFixed(1));render();};$('#minus').onclick=()=>{state.zoom=Math.max(1,+(state.zoom-.2).toFixed(1));render();};
function reset(){state.query='';state.route=false;state.topics=new Set(Object.keys(TOPICS));$('#search').value='';document.querySelectorAll('#topics input').forEach(i=>i.checked=true);render();}$('#reset').onclick=reset;
$('#start').onclick=()=>{reset();state.route=true;state.view='map';document.querySelector('[data-view="map"]').click();$('.atlas').scrollIntoView({behavior:'smooth',block:'start'});$('#map-scroll').scrollLeft=18*64*state.zoom;openEvent('sketchpad');};
const method=()=>openDialog(`<div class="eyebrow">О ПРОЕКТЕ</div><h2>История как сеть передачи идей</h2><p>«Нити» — прототип русскоязычной карты истории IT. Сейчас это 16 событий, три исследовательские линии и 12 объяснённых связей за 1947–1993 годы.</p><h3>КАК ИССЛЕДОВАТЬ</h3><p>Прокручивайте шкалу по горизонтали. Нажмите на событие, чтобы узнать о проблеме, участниках и связанных работах. Разделы «Люди» и «Институты» позволяют исследовать те же события через участников. Поиск работает по именам, названиям и текстам событий.</p><h3>ЧТО ОЗНАЧАЮТ ЛИНИИ</h3><p>Сплошная линия — развитие технологии или институциональная преемственность. Пунктир — передача идей, описанная в источнике. Фиолетовые связи в полупроводниковой линии показывают переход людей. Конкретное основание каждой связи приведено в карточке.</p><h3>ГРАНИЦЫ ВЫБОРКИ</h3><p>Это редакционная выборка, а не полный граф истории или доказательство единственной цепочки причин. Годы иногда обозначают публикацию или раннюю версию, а не начало исследования. Оценки «что изменилось» и формулировки проблем — краткое редакционное объяснение. Источники преимущественно на английском.</p><p class="note">Plex включён как отдельная линия моделирования в MIT. Его статус «прародителя ООП» требует дополнительного исследования; стрелка влияния на ООП не добавлена.</p><h3>БИБЛИОТЕКА ИСТОЧНИКОВ</h3>${Object.keys(SOURCES).map(sourceHTML).join('')}`);$('#about').onclick=method;$('#method').onclick=method;
render();
